    resp_idx += 1

    action = Action(**json.loads(response_str))
    # Simulate feedback loop
    return action, current_state.location, current_state.has_key

def update_state(action: Action, prev_state: GameState) -> GameState:
    loc = prev_state.location
    items = []

    if action.type == "ask":
        msg = ask(action.params.get("question"))
        loc = msg.get("location", loc)
        items.append(msg.get("message"))
    elif action.type == "move":
        direction = action.params.get("direction")
        loc = msg := move(direction) if msg else loc
        if isinstance(msg, str):
            loc = msg
        items.append(msg)
    elif action.type == "take":
