import dspy
from pydantic import BaseModel
from typing import List, Dict

# Step 1: Define Pydantic models
class RideOffer(BaseModel):
    id: str
    price: float
    driver_name: str

class RiderProfile(BaseModel):
    name: str
    email: str

class BookingRequest(BaseModel):
    offer_id: str
    rider_name: str

# Step 2: Define tool signatures with typed params
class SearchSignature(dspy.Signature):
    query: str = None
    max_results: int = dspy.KWARGS

@search_signature.dsp_module()
def run_search(query: str, max_results: int) -> List[dict]:
    """Tool: Simulated search returning ride offers."""
    return [{"id": "1", "price": 15.0, "driver_name": "Alice"}]

class PickBestOfferSignature(dspy.Signature):
    offers: List[dict] = None

@pick_best_signature.dsp_module()
def pick_cheapest(offers: List[dict]) -> RideOffer:
    """Tool: Select cheapest offer from list."""
    return RideOffer(**min(offers, key=lambda x: x['price']))

class ConfirmBookingSignature(dspy.Signature):
    rider_profile: RiderProfile
    booking_request: BookingRequest

@confirm_booking_signature.dsp_module()
def confirm_booking(rider: RiderProfile, booking: BookingRequest) -> bool:
    """Tool: Confirm booking with typed inputs."""
    return True

# Step 3: Compose workflow in DSPy Module
class CarpoolWorkflow(dspy.Module):
    def forward(self, query: str, max_results: int = 5) -> bool:
        # Execute search
        raw_offers = self.search(query=query, max_results=max_results)

        # Parse dict responses into RideOffer list
        offers = [RideOffer(**offer) for offer in raw_offers]
        chosen_offer = self.pick_cheapest(offers=offers)

        # Confirm booking with typed inputs
        booking = BookingRequest(offer_id=chosen_offer.id, rider_name=self.rider_profile.name)
        success = self.confirm_booking(
            rider=self.rider_profile, 
            booking=booking
        )
        return success

    # Define internal tool calls via Predict modules
    @dspy.Predict
    def search(self, query: str, max_results: int) -> List[dict]:
        return []

    @dspy.Predict
    def pick_cheapest(self, offers: List[dict]) -> RideOffer:
        return RideOffer(id="1", price=15.0, driver_name="Alice")

    @dspy.Predict
    def confirm_booking(self, rider: RiderProfile, booking: BookingRequest) -> bool:
        return True

# Initialize example profile
rider_profile_example = RiderProfile(name="Bob", email="bob@example.com")
workflow = CarpoolWorkflow()

# Mock execution with example input
result = workflow(
    query="NYC to Boston",
    max_results=3,
    rider_profile=rider_profile_example
)
```
**Key Notes**:  
- Tools are explicitly typed using Pydantic models (`RideOffer`, `BookingRequest`).  
- `Module.forward()` chains steps with type-safe transitions between steps.  
- Example predictions use pre-defined mock data to ensure compatibility without live LM.  
- All attributes (e.g., `chosen_offer.price`) remain accessible as typed properties throughout the workflow.

